#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    const int INF = 1e9;
    int n = static_cast<int>(s.size());
    int answer = INF;

    const vector<string> endings = {"00", "25", "50", "75"};

    for (const string& ending : endings) {
        for (int i = 0; i < n; ++i) {
            if (s[i] != ending[0]) continue;

            for (int j = 0; j < n; ++j) {
                if (i == j || s[j] != ending[1]) continue;

                vector<pair<char, int>> digits;
                for (int k = 0; k < n; ++k) {
                    digits.push_back({s[k], k});
                }

                int moves = 0;

                int pos = 0;
                while (digits[pos].second != j) ++pos;
                while (pos < n - 1) {
                    swap(digits[pos], digits[pos + 1]);
                    ++pos;
                    ++moves;
                }

                pos = 0;
                while (digits[pos].second != i) ++pos;
                while (pos < n - 2) {
                    swap(digits[pos], digits[pos + 1]);
                    ++pos;
                    ++moves;
                }

                if (digits[0].first == '0') {
                    int firstNonZero = -1;
                    for (int k = 1; k < n - 2; ++k) {
                        if (digits[k].first != '0') {
                            firstNonZero = k;
                            break;
                        }
                    }

                    if (firstNonZero == -1) continue;

                    while (firstNonZero > 0) {
                        swap(digits[firstNonZero], digits[firstNonZero - 1]);
                        --firstNonZero;
                        ++moves;
                    }
                }

                answer = min(answer, moves);
            }
        }
    }

    cout << (answer == INF ? -1 : answer);
    return 0;
}

