int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    const int INF = 1e9;
    int n = static_cast<int>(s.size());
    int answer = INF;

    const vector<string> endings = {"00", "25", "50", "75"};

    for (const string& ending : endings) {
        for (int i = 0; i < n; ++i) {
            if (s[i] != ending[0]) continue;

            for (int j = 0; j < n; ++j) {
                if (i == j || s[j] != ending[1]) continue;

                string t = s;
                int cost = 0;
                int tensPos = i;
                int unitsPos = j;

                char units = t[unitsPos];
                t.erase(t.begin() + unitsPos);
                t.push_back(units);
                cost += n - 1 - unitsPos;

                if (tensPos > unitsPos) --tensPos;

                char tens = t[tensPos];
                t.erase(t.begin() + tensPos);
                t.insert(t.begin() + (n - 2), tens);
                cost += n - 2 - tensPos;

                if (t[0] == '0') {
                    int firstNonZero = -1;
                    for (int k = 1; k < n - 2; ++k) {
                        if (t[k] != '0') {
                            firstNonZero = k;
                            break;
                        }
                    }

                    if (firstNonZero == -1) continue;
                    cost += firstNonZero;
                }

                answer = min(answer, cost);
            }
        }
    }

    cout << (answer == INF ? -1 : answer);
    return 0;
}

